import { expect, test } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';

const shopper = 'dana.reed@example.com';
const goodPassword = 'Aurora-Storefront-1';

test('TC-001: Account locks on the fifth wrong password within 10 minutes', async ({ page }) => {
  const login = new LoginPage(page);
  await login.goto();

  await login.failSignIn(shopper, 5);

  await expect(login.errorMessage).toContainText('locked');
});

test('TC-003: Lockout message names the 30 minute duration', async ({ page }) => {
  const login = new LoginPage(page);
  await login.goto();

  await login.failSignIn(shopper, 5);

  await expect(login.errorMessage).toContainText('30 minutes');
});

test('TC-004: Successful sign-in resets the failed attempt counter', async ({ page }) => {
  const login = new LoginPage(page);
  await login.goto();

  await login.failSignIn(shopper, 4);
  await login.signIn(shopper, goodPassword);
  await login.expectAccountPage();
  await login.signOut();

  // The counter is cleared in the background; wait for that call instead of this pause.
  await page.waitForTimeout(1000);

  await login.goto();
  await login.failSignIn(shopper, 4);
  await login.signIn(shopper, goodPassword);
  await login.expectAccountPage();
});

